function demoApi(path,o={}){
 const [table,query='']=path.split('?');if(!demoTables[table])throw Error('Демо: непозната табела '+table);
 const params=new URLSearchParams(query),method=(o.method||'GET').toUpperCase(),body=o.body?JSON.parse(o.body):null,records=demoTables[table];
 const matches=(row,expr)=>{const ix=expr.indexOf('.');if(ix<0)return true;const key=expr.slice(0,ix),val=expr.slice(ix+1),actual=row[key];if(val.startsWith('eq.'))return String(actual??'')===val.slice(3);if(val.startsWith('neq.'))return String(actual??'')!==val.slice(4);if(val.startsWith('in.('))return val.slice(4,-1).split(',').map(x=>x.trim()).includes(String(actual));if(val.startsWith('is.null'))return actual==null;if(val.startsWith('gt.'))return Number(actual)>Number(val.slice(3));return true};
 if(method==='PATCH'||method==='DELETE'){const found=records.filter(row=>[...params.entries()].filter(([k])=>k!=='select'&&k!=='order'&&k!=='limit').every(([k,v])=>matches(row,k+'.'+v)));found.forEach(row=>{if(method==='PATCH')Object.assign(row,body)});return Promise.resolve(null)}
 if(method==='POST'){const row={id:Math.max(0,...records.map(x=>Number(x.id)||0))+1,...body};records.push(row);return Promise.resolve([row])}
 let result=records.filter(row=>[...params.entries()].filter(([k])=>!['select','order','limit','offset'].includes(k)).every(([k,v])=>matches(row,k+'.'+v)));
 const order=params.get('order');if(order){const [key,dir]=order.split('.');result.sort((a,b)=>{const x=a[key],y=b[key];return (x>y?1:x<y?-1:0)*(dir==='desc'?-1:1)})}
 if(params.has('limit'))result=result.slice(0,Number(params.get('limit')));if(params.has('select')){const cols=params.get('select').split(',');if(!cols.includes('*'))result=result.map(row=>Object.fromEntries(cols.filter(k=>k in row).map(k=>[k,row[k]])))}
 return Promise.resolve(JSON.parse(JSON.stringify(result)));
}
const api=async(p,o={})=>{if(DEMO)return demoApi(p,o);const r=await fetch(U+'/rest/v1/'+p,{cache:'no-store',...o,headers:{...H,...(o.headers||{})}});const body=await r.text();if(!r.ok)throw Error(body||('HTTP '+r.status));if(r.status===204||!body.trim())return null;try{return JSON.parse(body)}catch(err){throw Error('База је вратила неочекиван одговор ('+r.status+'): '+body.slice(0,240))}};

/* Нове поруџбине које чекају потврду: провера одмах и затим на сваких 30 секунди. */
let pendingOrderIds=new Set();
let newestPendingOrderId=null;
async function checkPendingOrders(){
 const box=document.getElementById('pendingNotice');
 const title=document.getElementById('pendingTitle');
 const details=document.getElementById('pendingDetails');
 if(!box)return;
 try{
  const pending=await api('porudzbine?select=id,created_at,status,telefon,ukupna_cena,napomena&status=in.(nova,primljeno)&order=created_at.desc&limit=100')||[];
  const ids=new Set(pending.map(x=>String(x.id)));
  const fresh=pending.filter(x=>!pendingOrderIds.has(String(x.id)));
  pendingOrderIds=ids;
  if(!pending.length){box.classList.add('hidden');return}
  const newest=pending[0];
  newestPendingOrderId=newest.id;
  box.classList.remove('hidden');
  title.textContent=pending.length===1?'1 нова поруџбина чека потврду':pending.length+' нових поруџбина чека потврду';
  const created=newest.created_at?new Date(newest.created_at).toLocaleString('sr-RS',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}):'време није доступно';
  details.textContent='Најновија је поруџбина #'+newest.id+' · '+created+' · '+(Number(newest.ukupna_cena||0).toLocaleString('sr-RS')+' дин.')+(fresh.length?' · '+(fresh.length===1?'Стигла је нова поруџбина!':'Стигле су нове поруџбине!'):'');
  box.title=pending.map(x=>'#'+x.id+' · '+(x.telefon||'телефон није унет')).join('\n');
 }catch(err){
  console.warn('Провера нових поруџбина није успела:',err);
  details.textContent='Провера тренутно није успела. Притисни „Провери“ или освежи страницу.';
  box.classList.remove('hidden');
  title.textContent='Није могуће проверити нове поруџбине';
 }
}
