async function createAndAttachPoint(orderId,name,address){try{const created=await api('punktovi',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({name,city:'Београд',address,is_active:'true',aktivan:'true',description:'Пункт додат из поруџбине #'+orderId})});const point=Array.isArray(created)?created[0]:created;if(!point?.id)throw Error('База није вратила ID новог пункта.');await attachPointToTour(point.id);await savePointToOrder(orderId,point.id);alert('Направљен је пункт „'+name+'“ и повезан са поруџбином.')}catch(x){alert('Нисам успео да направим пункт: '+x.message)}}
async function attachPointToTour(pointId){try{await api('tura_punktovi',{method:'POST',headers:{Prefer:'resolution=ignore-duplicates,return=minimal'},body:JSON.stringify({tura_id:Number(tour.id),punkt_id:Number(pointId),aktivan:true})})}catch(x){if(!String(x.message).includes('409'))throw x}}
async function savePointToOrder(orderId,pointId){await api('porudzbine?id=eq.'+encodeURIComponent(orderId),{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({punkt_id:Number(pointId),updated_at:new Date().toISOString()})});await reload()}

async function assign(id){const f=document.querySelector('[data-s="'+id+'"]').value;if(!f)return alert('Изабери газдинство.');try{await api('stavke_porudzbine?id=eq.'+id,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({dodijeljeno_gazdinstvo_id:n(f)})});await reload()}catch(x){alert('Грешка: '+x.message)}}

function fmt(v){return Number(v||0).toLocaleString('sr-RS',{maximumFractionDigits:2})}

function procurementPackages(){const map=new Map();rows.forEach(r=>{const p=productFor(r),direct=variantFor(r),size=n(direct?.package_value||r.package_size),packageUnit=String(direct?.package_unit||r.package_unit||r.quantity_unit||r.jedinica||'').toLowerCase(),v=direct||variants.find(x=>String(x.product_id)===String(p?.id)&&n(x.package_value)===size&&String(x.package_unit||'').toLowerCase()===packageUnit),count=n(r.package_count||r.broj_pakovanja)||(size>0?n(r.total_quantity||r.kolicina)/size:0);if(!p||!v||!size||count<=0)return;const key=String(p.id)+'|'+String(v.id);if(!map.has(key))map.set(key,{key,productId:p.id,productName:p.name||r.proizvod,product:p,variantId:v.id,variant:v,label:v.name||v.size_label||('Паковање '+fmt(size)+' '+(v.package_unit||'')),size,unit:v.package_unit||r.package_unit||r.quantity_unit||r.jedinica||'',count:0,rows:[]});const x=map.get(key);x.count+=count;x.rows.push(r)});return [...map.values()].sort((a,b)=>String(a.productName).localeCompare(String(b.productName),'sr')||String(a.label).localeCompare(String(b.label),'sr'))}
function procCustomerCount(allocation,lineId){const list=Array.isArray(allocation?.raspodela_kupcima)?allocation.raspodela_kupcima:[];const item=list.find(x=>String(x.stavka_id)===String(lineId));return n(item?.broj_pakovanja)}
function procAssignedToOtherFarms(lineId,allocated,skipId){return allocated.filter(a=>String(a.id)!==String(skipId)).reduce((sum,a)=>sum+procCustomerCount(a,lineId),0)}
