 const id=String(a.id),isOpen=openProcCustomerAllocations.has(id),list=Array.isArray(a.raspodela_kupcima)?a.raspodela_kupcima:[],assignedHere=list.reduce((sum,x)=>sum+n(x.broj_pakovanja),0),free=Math.max(0,n(a.broj_pakovanja)-assignedHere);
 const customerRows=selected.rows.map(r=>{const demand=n(r.package_count||r.broj_pakovanja)||(n(r.total_quantity||r.kolicina)/Math.max(1,n(r.package_size||selected.size)));const here=procCustomerCount(a,r.id),others=procAssignedToOtherFarms(r.id,allocated,a.id),max=Math.max(0,demand-others),label=orderLabel(r.porudzbina_id,[r]),meta=pointNameForOrder(orderMeta.find(o=>String(o.id)===String(r.porudzbina_id)));return '<div class="proc-customer-split-row"><div><b>'+e(label)+'</b><small>'+e(meta)+' · поруџбина #'+e(r.porudzbina_id)+'</small><span>Потребно '+fmt(demand)+' пак. · већ додељено другим газдинствима '+fmt(others)+'</span></div><label><span>Одавде</span><input type="number" min="0" max="'+fmt(Math.min(n(a.broj_pakovanja),max))+'" step="1" value="'+fmt(here)+'" data-proc-customer-count="'+e(r.id)+'"></label></div>'}).join('');
