function renderManifest(){const stopOrder=new Map(routeStops.slice().sort((a,b)=>{const at=String(a.vreme||'').slice(0,5),bt=String(b.vreme||'').slice(0,5);if(at&&bt)return at.localeCompare(bt)||n(a.redosled)-n(b.redosled);if(at)return -1;if(bt)return 1;return n(a.redosled)-n(b.redosled)||n(a.punkt_id)-n(b.punkt_id)}).map((s,i)=>[String(s.punkt_id),{i,time:s.vreme||''}]));const os=orderGroups().map(o=>({...o,deliverable:o.rs.filter(r=>n(r.preuzeta_kolicina)>0),pending:o.rs.filter(r=>n(r.preuzeta_kolicina)<=0)})).filter(o=>o.rs.length).sort((a,b)=>{const pa=stopOrder.get(String(a.m?.punkt_id))||{i:9999,time:''},pb=stopOrder.get(String(b.m?.punkt_id))||{i:9999,time:''};return pa.i-pb.i||String(a.id).localeCompare(String(b.id),undefined,{numeric:true})});const totalAll=os.reduce((s,o)=>s+o.deliverable.reduce((x,r)=>x+salePrice(r)*n(r.preuzeta_kolicina),0),0);const done=os.filter(o=>o.deliverable.every(r=>n(r.isporucena_kolicina)>=n(r.preuzeta_kolicina))).length;const summary='<div class="stats"><div class="stat"><b>'+os.length+'</b><span>купаца за доставу</span></div><div class="stat"><b>'+done+'/'+os.length+'</b><span>извршених достава</span></div><div class="stat"><b>'+totalAll.toLocaleString('sr-RS')+' дин.</b><span>укупно за наплату</span></div></div>';const cards=os.map(o=>{const p=stopOrder.get(String(o.m?.punkt_id));const complete=o.deliverable.every(r=>n(r.isporucena_kolicina)>=n(r.preuzeta_kolicina));const total=o.deliverable.reduce((s,r)=>s+salePrice(r)*n(r.preuzeta_kolicina),0);const items=o.deliverable.map(r=>{const qty=n(r.preuzeta_kolicina),unitPrice=salePrice(r),delivered=n(r.isporucena_kolicina);return '<div class="item"><div class="itemtop"><div><div class="productname">'+e(r.proizvod)+'</div><div class="meta">'+e(qty+' '+unit(r))+' × '+e(unitPrice.toLocaleString('sr-RS'))+' дин./јед.</div>'+(delivered>0&&delivered<qty?'<div class="status warn">Делимично предато: '+e(delivered+' '+unit(r))+'</div>':'')+'</div><div class="qty">'+e((qty*unitPrice).toLocaleString('sr-RS'))+' дин.</div></div></div>'}).join('');return '<div class="buyer"><div class="buyerhead"><div><div class="buyername">'+e(orderLabel(o.id,o.deliverable))+'</div><div class="hint">Поруџбина #'+e(o.id)+(o.m?.telefon?' · '+e(o.m.telefon):'')+'</div><div class="hint">'+e(pointNameForOrder(o.m))+(p?.time?' · Долазак '+e(p.time):' · Сатница није унета')+'</div><div class="hint">Достављач: <b>'+e(o.m?.dostavljac||tour?.dostavljac||'Није додељен')+'</b></div></div><div style="text-align:right"><b>'+total.toLocaleString('sr-RS')+' дин.</b><div class="status '+(complete?'ok':'warn')+'">'+(complete?'ИЗВРШЕНО':'ЧЕКА ДОСТАВУ')+'</div></div></div>'+items+'<div class="item"><label style="display:flex;align-items:center;gap:10px;font-weight:850"><input type="checkbox" data-delivery-done="'+e(o.id)+'" '+(complete?'checked':'')+' style="width:20px;height:20px;flex:0 0 20px"> Достава извршена — роба предата купцу</label><div class="hint" style="margin-top:6px">Означавање бележи стварно испоручене количине и чува статус за следећи пут.</div></div></div>'}).join('');document.getElementById('manifest').innerHTML='<div class="point-actions" style="margin:0 0 14px"><button type="button" class="primary" id="copyViberSchedule">КОПИРАЈ САТНИЦУ ЗА VIBER</button></div><div id="viberCopyStatus" class="hint" style="margin-bottom:10px"></div>'+summary+(cards||'<div class="empty">Нема робе за доставу. Када у делу „Газдинства и преузимање“ унесеш стварно преузете количине, појавиће се овде.</div>');document.getElementById('copyViberSchedule').onclick=copyViberSchedule;document.querySelectorAll('[data-delivery-done]').forEach(c=>c.onchange=()=>setDeliveryDone(c.dataset.deliveryDone,c.checked))}
async function copyViberOrdersSchedule(){const stopOrder=new Map(routeStops.slice().sort((a,b)=>{const at=String(a.vreme||'').slice(0,5),bt=String(b.vreme||'').slice(0,5);if(at&&bt)return at.localeCompare(bt)||n(a.redosled)-n(b.redosled);if(at)return -1;if(bt)return 1;return n(a.redosled)-n(b.redosled)||n(a.punkt_id)-n(b.punkt_id)}).map((s,i)=>[String(s.punkt_id),{i,time:s.vreme||''}]));const os=orderGroups().filter(o=>o.rs.length).sort((a,b)=>{const an=orderLabel(a.id,a.rs).toLocaleLowerCase('sr-RS'),bn=orderLabel(b.id,b.rs).toLocaleLowerCase('sr-RS');const ar=/\\bristo\\b/.test(an),br=/\\bristo\\b/.test(bn);if(ar!==br)return ar?-1:1;const pa=stopOrder.get(String(a.m?.punkt_id))||{i:9999,time:''},pb=stopOrder.get(String(b.m?.punkt_id))||{i:9999,time:''};return pa.i-pb.i||String(a.id).localeCompare(String(b.id),undefined,{numeric:true})});const date=tour?.datum?new Date(tour.datum+'T00:00:00').toLocaleDateString('sr-RS'):'';const groups=new Map();routeStops.slice().sort((a,b)=>{const at=String(a.vreme||'').slice(0,5),bt=String(b.vreme||'').slice(0,5);if(at&&bt)return at.localeCompare(bt)||n(a.redosled)-n(b.redosled);if(at)return -1;if(bt)return 1;return n(a.redosled)-n(b.redosled)||n(a.punkt_id)-n(b.punkt_id)}).forEach(s=>{const id=String(s.punkt_id),point=pointMeta.find(p=>String(p.id)===id);groups.set(id,{name:point?.name||'Пункт #'+id,time:s.vreme||point?.vreme||'',orders:[]})});os.forEach(o=>{const id=o.m?.punkt_id?String(o.m.punkt_id):'none';if(!groups.has(id)){const stop=stopOrder.get(id),point=pointMeta.find(p=>String(p.id)===id);groups.set(id,{name:point?.name||'Пункт није одређен',time:stop?.time||point?.vreme||'',orders:[]})}groups.get(id).orders.push(o)});const lines=['🕒 ВРЕМЕ ДОСТАВЕ — НАРУЧИ ДОМАЋЕ'+(date?' · '+date:''),''];let pointIndex=0;for(const g of groups.values()){pointIndex++;lines.push('📍 '+g.name.toLocaleUpperCase('sr-RS')+' — '+(g.time?'ВРЕМЕ: '+String(g.time).slice(0,5):'ВРЕМЕ НИЈЕ УНЕТО'));lines.push('');g.orders.sort((a,b)=>{const an=orderLabel(a.id,a.rs).toLocaleLowerCase('sr-RS'),bn=orderLabel(b.id,b.rs).toLocaleLowerCase('sr-RS');const ar=/\\bristo\\b/.test(an),br=/\\bristo\\b/.test(bn);return ar!==br?(ar?-1:1):an.localeCompare(bn,'sr')}).forEach(o=>{lines.push('👤 '+orderLabel(o.id,o.rs));lines.push('Поруџбина:');o.rs.forEach(r=>{lines.push('• '+r.proizvod+' — '+fmt(q(r))+' '+unit(r))});lines.push('')});lines.push('────────────────');lines.push('')}if(!groups.size){alert('Овој тури још нису додати пунктови.');return}const text=lines.join('\n').trim();try{if(navigator.clipboard&&navigator.clipboard.writeText){await navigator.clipboard.writeText(text)}else throw Error('clipboard unavailable');document.getElementById('viberOrdersCopyStatus').textContent='Сатница са оквирним временом и свим нарученим производима по купцу је копирана. Налепи је у Viber.'}catch(err){const ta=document.createElement('textarea');ta.value=text;ta.style.width='100%';ta.style.minHeight='260px';ta.style.marginTop='8px';const status=document.getElementById('viberOrdersCopyStatus');status.textContent='Аутоматско копирање није успело. Означи текст испод и копирај га ручно.';status.appendChild(ta);ta.focus();ta.select()}}
async function copyViberSchedule(){const stopOrder=new Map(routeStops.slice().sort((a,b)=>{const at=String(a.vreme||'').slice(0,5),bt=String(b.vreme||'').slice(0,5);if(at&&bt)return at.localeCompare(bt)||n(a.redosled)-n(b.redosled);if(at)return -1;if(bt)return 1;return n(a.redosled)-n(b.redosled)||n(a.punkt_id)-n(b.punkt_id)}).map((s,i)=>[String(s.punkt_id),{i,time:s.vreme||''}]));const os=orderGroups().map(o=>({...o,deliverable:o.rs.filter(r=>n(r.preuzeta_kolicina)>0)})).filter(o=>o.deliverable.length).sort((a,b)=>{const pa=stopOrder.get(String(a.m?.punkt_id))||{i:9999,time:''},pb=stopOrder.get(String(b.m?.punkt_id))||{i:9999,time:''};return pa.i-pb.i||String(a.id).localeCompare(String(b.id),undefined,{numeric:true})});const date=tour?.datum?new Date(tour.datum+'T00:00:00').toLocaleDateString('sr-RS'):'';const lines=['📦 САТНИЦА ЗА ПРЕУЗИМАЊЕ — НАРУЧИ ДОМАЋЕ'+(date?' · '+date:''),''];os.forEach((o,i)=>{const stop=stopOrder.get(String(o.m?.punkt_id));lines.push((i+1)+'. '+orderLabel(o.id,o.deliverable));lines.push('ПРЕУЗЕТО:');lines.push(o.deliverable.length?o.deliverable.map(r=>'• '+r.proizvod+' — '+fmt(n(r.preuzeta_kolicina))+' '+unit(r)).join('\n'):'Ништа још није преузето');if(o.pending.length){lines.push('ЈОШ НИЈЕ ПРЕУЗЕТО:');lines.push(o.pending.map(r=>'• '+r.proizvod+' — наручено '+fmt(q(r))+' '+unit(r)).join('\n'))}lines.push('Где преузима: '+pointNameForOrder(o.m));lines.push('У колико сати: '+(stop?.time||'сатница није унета'));lines.push('')});if(!os.length){alert('Нема поруџбина у активној тури.');return}const text=lines.join('\n').trim();try{if(navigator.clipboard&&navigator.clipboard.writeText){await navigator.clipboard.writeText(text)}else throw Error('clipboard unavailable');document.getElementById('viberCopyStatus').textContent='Сатница је копирана. Сада је налепи у Viber групу.'}catch(err){const ta=document.createElement('textarea');ta.value=text;ta.style.width='100%';ta.style.minHeight='220px';ta.style.marginTop='8px';const status=document.getElementById('viberCopyStatus');status.textContent='Аутоматско копирање није успело. Означи текст испод и копирај га:';status.appendChild(ta);ta.focus();ta.select()}}
async function setDeliveryDone(orderId,done){const o=orderGroups().find(x=>String(x.id)===String(orderId));if(!o)return;const deliverable=o.rs.filter(r=>n(r.preuzeta_kolicina)>0);if(!deliverable.length){alert('Нема стварно преузете робе за ову поруџбину.');return}try{for(const r of deliverable){const qty=done?n(r.preuzeta_kolicina):0;await api('stavke_porudzbine?id=eq.'+encodeURIComponent(r.id),{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({isporucena_kolicina:qty})})}await reload();show('manifest')}catch(x){alert('Статус доставе није сачуван: '+x.message);await reload();show('manifest')}}
function renderRoute(){const root=document.getElementById('route');const sorted=routeStops.slice().sort((a,b)=>n(a.redosled)-n(b.redosled)||n(a.punkt_id)-n(b.punkt_id));const routeIds=new Set(sorted.map(s=>String(s.punkt_id)));const available=pointMeta.filter(p=>!routeIds.has(String(p.id)));const addPointHtml='<div class="buyer"><div class="buyername">Пунктови у овој тури</div><div class="item"><label class="hint">Додај постојећи пункт у туру<select id="addRoutePoint"><option value="">Изабери пункт</option>'+available.map(p=>'<option value="'+e(p.id)+'">'+e(p.name)+(p.address?' — '+e(p.address):'')+'</option>').join('')+'</select></label><div class="point-actions"><button class="primary" id="addRoutePointButton">Додај пункт у туру</button></div><div class="hint">Време се подешава за сваки пункт. Поруџбине се затим додељују конкретном пункту.</div></div></div>';const stopHtml=sorted.map((s,i)=>{const p=pointMeta.find(x=>String(x.id)===String(s.punkt_id));const os=orderGroups().filter(o=>String(o.m?.punkt_id)===String(s.punkt_id));return '<div class="buyer"><div class="buyerhead"><div><div class="buyername">'+(i+1)+'. '+e(p?.name||('Пункт #'+s.punkt_id))+'</div><div class="hint">'+e(p?.address||p?.city||'Адреса није унета')+'</div><div class="item"><label class="hint">Време доласка на пункт<input type="time" id="routeTime-'+s.punkt_id+'" value="'+e(s.vreme||'')+'"></label><div class="point-actions"><button class="primary" data-save-time="'+s.punkt_id+'">Сачувај време</button></div></div><div class="hint">'+os.length+' поруџбина'+(s.vreme?' · Време у овој тури: '+e(s.vreme):'')+'</div></div><div class="point-actions"><button data-route-up="'+s.punkt_id+'" '+(i===0?'disabled':'')+'>↑</button><button data-route-down="'+s.punkt_id+'" '+(i===sorted.length-1?'disabled':'')+'>↓</button></div></div>'+os.map(o=>'<div class="item"><b>'+e(orderLabel(o.id,o.rs))+'</b><div class="meta">Поруџбина #'+e(o.id)+' · '+e(o.m?.telefon||'')+' · '+e(o.rs.reduce((sum,r)=>sum+q(r),0)+' ставки')+'</div><label class="hint">Пункт за ову поруџбину<select id="routeOrderPoint-'+e(o.id)+'"><option value="">Без пункта</option>'+pointMeta.map(pt=>'<option value="'+e(pt.id)+'" '+(String(o.m?.punkt_id||'')===String(pt.id)?'selected':'')+'>'+e(pt.name)+(pt.vreme?' — '+e(pt.vreme):'')+'</option>').join('')+'</select></label><div class="point-actions"><button class="primary" data-save-route-order="'+e(o.id)+'">Сачувај пункт поруџбине</button></div></div>').join('')+'</div>'}).join('');const noPoint=orderGroups().filter(o=>!o.m?.punkt_id);const unassignedHtml=noPoint.length?'<div class="buyer"><div class="buyername">Поруџбине без пункта</div>'+noPoint.map(o=>'<div class="item"><b>'+e(orderLabel(o.id,o.rs))+'</b><div class="meta">Поруџбина #'+e(o.id)+' · '+e(o.m?.telefon||'')+'</div><label class="hint">Изабери пункт<select id="routeOrderPoint-'+e(o.id)+'"><option value="">Без пункта</option>'+pointMeta.map(pt=>'<option value="'+e(pt.id)+'">'+e(pt.name)+(pt.vreme?' — '+e(pt.vreme):'')+'</option>').join('')+'</select></label><div class="point-actions"><button class="primary" data-save-route-order="'+e(o.id)+'">Додели пункт</button></div></div>').join('')+'</div>':'';root.innerHTML='<div class="buyer"><div class="item"><label class="hint">Достављач за ову туру<input id="tourDeliverer" value="'+e(tour?.dostavljac||'')+'" placeholder="Ко вози ову туру?"></label><div class="point-actions"><button class="primary" id="saveTourDeliverer">Сачувај достављача за туру</button></div></div></div>'+addPointHtml+(stopHtml||'<div class="empty">Овој тури још нису додати пунктови.</div>')+unassignedHtml+'<div class="hint" style="margin-top:10px">Овде се уређују пунктови туре, редослед, време доласка и распоред поруџбина. Почетни списак поруџбина приказује сачувано стање.</div>';document.getElementById('saveTourDeliverer').onclick=saveTourDeliverer;document.getElementById('addRoutePointButton').onclick=addRoutePointToTour;document.querySelectorAll('[data-route-up],[data-route-down]').forEach(b=>b.onclick=()=>moveRouteStop(Number(b.dataset.routeUp||b.dataset.routeDown),b.hasAttribute('data-route-up')?-1:1));document.querySelectorAll('[data-save-time]').forEach(b=>b.onclick=()=>saveRoutePointTime(Number(b.dataset.saveTime)));document.querySelectorAll('[data-save-route-order]').forEach(b=>b.onclick=()=>saveRouteOrderPoint(b.dataset.saveRouteOrder))}
async function addRoutePointToTour(){const value=document.getElementById('addRoutePoint')?.value;if(!value)return alert('Изабери пункт који додајеш у туру.');try{await attachPointToTour(Number(value));await reload();show('route');alert('Пункт је додат у туру.')}catch(x){alert('Пункт није додат у туру: '+x.message)}}
async function saveRoutePointTime(pointId){const value=document.getElementById('routeTime-'+pointId)?.value||null;try{await api('tura_punktovi?tura_id=eq.'+encodeURIComponent(tour.id)+'&punkt_id=eq.'+encodeURIComponent(pointId),{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({vreme:value})});let latest=await api('tura_punktovi?select=tura_id,punkt_id,redosled,aktivan,vreme&tura_id=eq.'+encodeURIComponent(tour.id)+'&order=redosled.asc,punkt_id.asc')||[];latest.sort((a,b)=>{const at=a.vreme||'',bt=b.vreme||'';if(at&&bt)return at.localeCompare(bt)||n(a.redosled)-n(b.redosled);if(at)return -1;if(bt)return 1;return n(a.redosled)-n(b.redosled)||n(a.punkt_id)-n(b.punkt_id)});for(let i=0;i<latest.length;i++){await api('tura_punktovi?tura_id=eq.'+encodeURIComponent(tour.id)+'&punkt_id=eq.'+encodeURIComponent(latest[i].punkt_id),{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({redosled:(i+1)*10})})}await reload();show('route');alert(value?'Време је сачувано. Пункт је аутоматски премештен на одговарајуће место у рути и редослед је ажуриран и у приказу поруџбина.':'Време је обрисано. Пунктови су поново поређани, а они без сатнице су после пунктова са одређеним временом.')}catch(x){alert('Време или редослед нису сачувани: '+x.message)}}
async function saveRouteOrderPoint(orderId){const value=document.getElementById('routeOrderPoint-'+orderId)?.value||'';try{if(value)await attachPointToTour(Number(value));await api('porudzbine?id=eq.'+encodeURIComponent(orderId),{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({punkt_id:value?Number(value):null,updated_at:new Date().toISOString()})});await reload();show('route');alert(value?'Пункт поруџбине је сачуван, а пункт је обезбеђен у овој тури.':'Поруџбина је сачувана без пункта.')}catch(x){alert('Пункт поруџбине није сачуван: '+x.message)}}

async function saveTourDeliverer(){const value=(document.getElementById('tourDeliverer')?.value||'').trim();try{await api('ture?id=eq.'+encodeURIComponent(tour.id),{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({dostavljac:value||null})});tour.dostavljac=value;renderRoute();alert(value?'Достављач за туру је сачуван.':'Достављач за туру је уклоњен.')}catch(x){alert('Достављач за туру није сачуван: '+x.message)}}
async function moveRouteStop(pointId,delta){const sorted=routeStops.slice().sort((a,b)=>n(a.redosled)-n(b.redosled)||n(a.punkt_id)-n(b.punkt_id));const i=sorted.findIndex(x=>n(x.punkt_id)===pointId),j=i+delta;if(i<0||j<0||j>=sorted.length)return;[sorted[i],sorted[j]]=[sorted[j],sorted[i]];try{for(let k=0;k<sorted.length;k++){await api('tura_punktovi?tura_id=eq.'+encodeURIComponent(tour.id)+'&punkt_id=eq.'+encodeURIComponent(sorted[k].punkt_id),{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({redosled:(k+1)*10})})}routeStops=sorted.map((x,k)=>({...x,redosled:(k+1)*10}));renderRoute()}catch(x){alert('Редослед руте није сачуван: '+x.message)}}
function renderDebt(){const d=payouts.filter(x=>!x.is_paid&&n(x.total_amount)>0),total=d.reduce((s,x)=>s+n(x.total_amount),0),planned={};rows.forEach(r=>{const fid=String(r.dodijeljeno_gazdinstvo_id||'');if(!fid)return;const remaining=Math.max(0,q(r)-n(r.preuzeta_kolicina));if(!remaining)return;planned[fid]=(planned[fid]||0)+remaining*price(r)});const plannedHtml=Object.entries(planned).filter(([,amount])=>amount>0).sort((a,b)=>fname(a[0]).localeCompare(fname(b[0]),'sr')).map(([fid,amount])=>'<div class="debt"><div class="debtrow"><div><div class="farmname">'+e(fname(fid))+'</div><div class="hint">Планирано · још није преузето у тури '+e(tour?.id||'')+'</div></div><div class="amount">'+amount.toLocaleString('sr-RS')+' дин.</div></div></div>').join('');document.getElementById('debt').innerHTML='<div class="notice">Планирано је процена вредности додељене робе која још није преузета. Стварно дуговање настаје тек када евидентираш преузимање и рачуна се само за стварно преузету количину.</div><div class="stats"><div class="stat"><b>'+d.length+'</b><span>стварна неплаћена дуговања</span></div><div class="stat"><b>'+total.toLocaleString('sr-RS')+'</b><span>дин. стварни дуг укупно</span></div><div class="stat"><b>'+d.filter(x=>String(x.tura_id)===String(tour.id)).length+'</b><span>стварна дуговања ове туре</span></div></div><h3>Планирано за преузимање</h3>'+(plannedHtml||'<div class="empty">Нема додељене робе која чека преузимање.</div>')+'<h3>Стварна дуговања</h3>'+(d.length?d.map(x=>'<div class="debt"><div class="debtrow"><div><div class="farmname">'+e(fname(x.producer_id))+'</div><div class="hint">Стварно дуговање · тура '+e(x.tura_id)+' · '+e(x.period||'')+'</div></div><div class="amount">'+n(x.total_amount).toLocaleString('sr-RS')+' дин.</div></div><button class="pay" data-pay="'+x.id+'">ПЛАЋЕНО — означи као плаћено</button></div>').join(''):'<div class="empty">Нема неплаћених стварних дуговања.</div>');document.querySelectorAll('[data-pay]').forEach(b=>b.onclick=()=>pay(b.dataset.pay))}
