document.getElementById('tourSelect').onchange=async ev=>{const selected=tours.find(x=>String(x.id)===ev.target.value);if(!selected)return;tour=selected;try{await reload()}catch(x){alert('Не могу да учитам туру: '+x.message)}};(async()=>{const sel=document.getElementById('tourSelect');try{document.getElementById('tourTitle').textContent='Учитавање тура…';sel.innerHTML='<option value="">Учитавање тура…</option>';tours=await api('ture?select=id,naziv,datum,status&order=datum.desc,id.desc&limit=100')||[];if(!tours.length)throw Error('Supabase је одговорио, али није вратио ниједну туру.');tours.sort((a,b)=>{const aa=String(a.status||'').toLowerCase()==='open'?1:0,bb=String(b.status||'').toLowerCase()==='open'?1:0;return bb-aa||String(b.datum||'').localeCompare(String(a.datum||''))||n(b.id)-n(a.id)});sel.innerHTML=tours.map(t=>'<option value="'+e(t.id)+'">'+e(t.naziv||('Тура '+t.id))+' — '+e(t.datum||'без датума')+' · '+(String(t.status||'').toLowerCase()==='open'?'АКТИВНА':e(t.status||'без статуса'))+'</option>').join('');tour=tours.find(t=>String(t.status||'').toLowerCase()==='open')||tours[0];sel.value=String(tour.id);await reload();const routeHash=decodeURIComponent(location.hash.slice(1));const hashTabs={orders:'orders',procurement:'procurement',pickup:'procurement',route:'orders',manifest:'orders',deliverers:'orders',debt:'orders'};if(hashTabs[routeHash])show(hashTabs[routeHash]);else show('orders')}catch(x){const message=x?.message||'Непозната грешка';document.getElementById('tourTitle').textContent=tours.length?(tour?.naziv||'Тура је учитана'):'Туре нису учитане';document.getElementById('tourDate').textContent=tour?.datum?new Date(tour.datum+'T00:00:00').toLocaleDateString('sr-RS'):(tours.length?'Подаци о тури су доступни.':'Провери везу са базом и дозволе за читање.');document.getElementById('status').textContent=tours.length?'Проблем при учитавању података: '+message:message;if(!tours.length)sel.innerHTML='<option value="">Грешка при учитавању тура</option>';else if(tour)sel.value=String(tour.id);console.error('Грешка при учитавању туре или њених података:',x)}})();

