document.addEventListener('click',ev=>{const allProduct=ev.target.closest('[data-assign-product-all]');if(allProduct){assignNeedGroup('product',allProduct.dataset.assignProductAll);return}const allPackage=ev.target.closest('[data-assign-package-all]');if(allPackage){assignNeedGroup('package',allPackage.dataset.assignPackageAll);return}const move=ev.target.closest('[data-package-move]');if(move){const key=move.dataset.packageKey,idx=needPackageOrder.indexOf(key),next=idx+(move.dataset.packageMove==='up'?-1:1);if(idx<0||next<0||next>=needPackageOrder.length)return;[needPackageOrder[idx],needPackageOrder[next]]=[needPackageOrder[next],needPackageOrder[idx]];safeRender('померање паковања',renderNeeds);return}if(ev.target.closest('[data-packages-open-all]')){closedNeedPackages.clear();safeRender('отварање паковања',renderNeeds);return}if(ev.target.closest('[data-packages-close-all]')){document.querySelectorAll('[data-need-package]').forEach(b=>closedNeedPackages.add(b.dataset.needPackage));safeRender('затварање паковања',renderNeeds);return}const b=ev.target.closest('[data-need-package]');if(!b)return;const key=b.dataset.needPackage;if(closedNeedPackages.has(key))closedNeedPackages.delete(key);else closedNeedPackages.add(key);safeRender('паковања и купци',renderNeeds)});
